<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head','Clerk'],true)){http_response_code(403);exit('Access denied.');}
if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired. Refresh the page and try again.');}
$id=filter_var($_POST['book_id']??null,FILTER_VALIDATE_INT);$title=trim((string)($_POST['title']??''));$author=trim((string)($_POST['author']??''));$isbn=strtoupper(trim((string)($_POST['isbn']??'')));$publisher=trim((string)($_POST['publisher']??''));$subject=trim((string)($_POST['subject_area']??''));$shelf=trim((string)($_POST['shelf_location']??''));$year=trim((string)($_POST['publication_year']??''));$copies=filter_var($_POST['total_copies']??null,FILTER_VALIDATE_INT);$active=isset($_POST['active'])?1:0;
$invalid=$title===''||strlen($title)>180||$author===''||strlen($author)>160||strlen($isbn)>20||strlen($publisher)>160||strlen($subject)>100||strlen($shelf)>60||$copies===false||$copies<1||$copies>9999||($year!==''&&(!ctype_digit($year)||(int)$year<1400||(int)$year>(int)date('Y')));
if($invalid){$_SESSION['error']='Check the book details, publication year and number of copies.';header('Location: ../?page=library');exit;}
$pdo=db();try{$pdo->beginTransaction();if($id){$lock=$pdo->prepare('SELECT id FROM library_books WHERE id=:id FOR UPDATE');$lock->execute(['id'=>$id]);if(!$lock->fetch())throw new DomainException('Book record not found.');$loans=$pdo->prepare('SELECT COUNT(*) FROM library_loans WHERE book_id=:id AND returned_on IS NULL');$loans->execute(['id'=>$id]);if($copies<(int)$loans->fetchColumn())throw new DomainException('Copy count cannot be lower than the number of books currently on loan.');$q=$pdo->prepare('UPDATE library_books SET isbn=:isbn,title=:title,author=:author,publisher=:publisher,subject_area=:subject,shelf_location=:shelf,publication_year=:year,total_copies=:copies,active=:active WHERE id=:id');$q->execute(['isbn'=>$isbn?:null,'title'=>$title,'author'=>$author,'publisher'=>$publisher?:null,'subject'=>$subject?:null,'shelf'=>$shelf?:null,'year'=>$year?:null,'copies'=>$copies,'active'=>$active,'id'=>$id]);$bookId=$id;$event='library.book_updated';}else{$q=$pdo->prepare('INSERT INTO library_books(isbn,title,author,publisher,subject_area,shelf_location,publication_year,total_copies,active,created_by) VALUES(:isbn,:title,:author,:publisher,:subject,:shelf,:year,:copies,:active,:user)');$q->execute(['isbn'=>$isbn?:null,'title'=>$title,'author'=>$author,'publisher'=>$publisher?:null,'subject'=>$subject?:null,'shelf'=>$shelf?:null,'year'=>$year?:null,'copies'=>$copies,'active'=>$active,'user'=>$user['id']]);$bookId=(int)$pdo->lastInsertId();$event='library.book_created';}audit_log($event,'library_books',$bookId,['title'=>$title,'total_copies'=>$copies,'active'=>(bool)$active]);$pdo->commit();$_SESSION['notice']='Library book record saved.';}catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']=$e->getMessage();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Library book save failed: '.$e->getMessage());$_SESSION['error']=($e instanceof PDOException&&$e->getCode()==='23000')?'That ISBN is already in the catalog.':'Could not save the library book record.';}
header('Location: ../?page=library');exit;
